TASK:{"title":"SWEN3204 Software Architecture – Assignment 2: Short-Answer Questions","overview":"Answer six short questions applying architecture concepts to the CampusEats scenario. The assignment is worth 40 marks, including 4 marks for communication. Submit an individual, single-document response."}
RUBRIC:[{"id":"C1","name":"Q1 Quality attributes","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Two attributes that clearly matter most are chosen and justified from the scenario. Both scenarios have all six parts and both response measures are measurable."},{"label":"Proficient","min":3,"max":4,"desc":"Suitable attributes are chosen with some justification. Scenarios are mostly complete but one is missing a part or has a response measure that is not measurable."},{"label":"Developing","min":1,"max":2,"desc":"Attributes are named with little or no justification, or the scenarios are not in six-part form or are not measurable."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or irrelevant."}]},{"id":"C2","name":"Q2 Architectural style","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"A clear recommendation justified by at least two trade-offs that are specific to the scenario (team size, load profile, known problems). The downside of the recommendation is acknowledged."},{"label":"Proficient","min":3,"max":4,"desc":"A clear recommendation with two trade-offs, but one is generic or not linked to the scenario, or no downside is acknowledged."},{"label":"Developing","min":1,"max":2,"desc":"A recommendation with only one trade-off, or with generic textbook advantages and disadvantages only."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no recommendation."}]},{"id":"C3","name":"Q3 Availability calculation","weight":null,"max":8,"levels":[{"label":"Excellent","min":7,"max":8,"desc":"Parts (a), (b) and (c) are all correct with working shown, to the requested precision."},{"label":"Proficient","min":5,"max":6,"desc":"The method is correct throughout but there is one arithmetic or rounding slip, or exactly one part is incorrect."},{"label":"Developing","min":1,"max":4,"desc":"The series calculation is attempted but two or more parts are incorrect, or working is not shown."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no correct element."}]},{"id":"C4","name":"Q4 Resilience pattern","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"An appropriate pattern is named, its mechanism is explained correctly, it is applied to the outage, and at least one drawback or tuning consideration is given."},{"label":"Proficient","min":3,"max":4,"desc":"An appropriate pattern is named and explained correctly, but it is only loosely applied to the outage or no drawback or tuning consideration is given."},{"label":"Developing","min":1,"max":2,"desc":"A pattern is named but the explanation is incorrect or very thin."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or an unsuitable pattern."}]},{"id":"C5","name":"Q5 Consistency and availability","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Both choices are justified, the CAP theorem is used correctly, and a suitable concrete technique is named for each case."},{"label":"Proficient","min":3,"max":4,"desc":"Both choices are reasonable and techniques are named, but the CAP theorem is explained incorrectly or imprecisely, or one technique is missing."},{"label":"Developing","min":1,"max":2,"desc":"Choices are stated with little justification, or the CAP theorem is not used."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C6","name":"Q6 Architecture decision record","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"Context, Decision and Consequences are all present and specific to the scenario, with at least one positive and one negative consequence."},{"label":"Proficient","min":3,"max":4,"desc":"All three sections are present but the consequences are one-sided (no negative consequence) or the context is generic."},{"label":"Developing","min":1,"max":2,"desc":"One or more sections are missing or the record does not describe a decision."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C7","name":"Communication and format","weight":null,"max":4,"levels":[{"label":"Excellent","min":4,"max":4,"desc":"Every answer is within 150 words, terminology is precise, the required headings are used and sources are cited in IEEE style."},{"label":"Proficient","min":3,"max":3,"desc":"Clear writing, but one answer exceeds the word limit or there are minor citation or formatting problems."},{"label":"Developing","min":1,"max":2,"desc":"Several answers exceed the word limit, or the writing is hard to follow, or sources are not cited."},{"label":"Missing","min":0,"max":0,"desc":"Format requirements ignored."}]}]
MARKING:{"requirements":[{"id":"R1","met":"partial","where":"Question 1"},{"id":"R2","met":"yes","where":"Question 2"},{"id":"R3","met":"partial","where":"Question 3"},{"id":"R4","met":"partial","where":"Question 4"},{"id":"R5","met":"partial","where":"Question 5"},{"id":"R6","met":"partial","where":"Question 6"},{"id":"R7","met":"partial","where":"References"}],"technical_issues":[{"where":"Question 1","issue":"Availability response measure 'stay up most of the time' is not measurable."},{"where":"Question 2","issue":"Answer is about 181 words, exceeding the 150-word limit."},{"where":"Question 3(b)","issue":"0.00699 × 720 = 5.03 hours, not 3.5 hours."},{"where":"Question 3(c)","issue":"New end-to-end availability must multiply all components; 99.9975% is only payment availability. Correct end-to-end is about 99.80%, downtime about 1.46 h."},{"where":"Question 4","issue":"Circuit breaker Open/Closed states are reversed; Open should fail fast, Closed should pass calls."},{"where":"Question 5","issue":"CAP misuse: partition tolerance cannot be given up; in a partition choose C or A. Payment technique missing."},{"where":"Question 6","issue":"No negative consequence in the ADR."},{"where":"References","issue":"[2] is cited in Question 4 but absent from the reference list; assumptions are not stated."}],"overall":"Total 25/40. Strong Q2 and mostly good Q1/Q6, but Q3 has two wrong parts, Q4 reverses circuit-breaker states, Q5 misuses CAP and omits a payment technique, Q6 lacks a negative consequence, and Q2 exceeds the word limit with a missing reference.","criteria":[{"id":"C1","level":"Proficient","mark":4.0,"scale":6.0,"points":4.0,"max":6.0,"reasoning":"Performance and availability are well justified from the lunch peak and abandonment. The performance scenario has all six parts and a measurable p95 target. The availability scenario has six parts but its response measure is not measurable, so it is not Excellent.","evidence":[{"where":"Question 1","quote":"The two most important quality attributes are performance and availability"},{"where":"Question 1","quote":"Response measure: the system should stay up most of the time."}]},{"id":"C2","level":"Excellent","mark":6.0,"scale":6.0,"points":6.0,"max":6.0,"reasoning":"Clear modular-monolith recommendation. Trade-offs are scenario-specific: five developers versus operational overhead, and single-VM/deployment causes of known problems. The downside is acknowledged: no independent scaling and whole-process crash risk.","evidence":[{"where":"Question 2","quote":"I recommend against a full microservices rewrite for the next 12 months."},{"where":"Question 2","quote":"The trade-off I accept is that modules cannot be scaled independently"}]},{"id":"C3","level":"Developing","mark":3.0,"scale":8.0,"points":3.0,"max":8.0,"reasoning":"Part (a) is correct. Part (b) has an arithmetic error: 0.00699×720≈5.03 h, not 3.5 h. Part (c) computes payment availability correctly but then treats it as end-to-end availability; the other components must still multiply, giving about 99.80% and about 1.46 h downtime.","evidence":[{"where":"Question 3","quote":"A = 0.9995 × 0.999 × 0.9995 × 0.995 = 0.99301"},{"where":"Question 3","quote":"Downtime = (1 − 0.99301) × 720 = 0.00699 × 720 = 3.5 hours per month."},{"where":"Question 3","quote":"So the new availability of placing an order is 99.9975%"}]},{"id":"C4","level":"Developing","mark":2.0,"scale":5.0,"points":2.0,"max":5.0,"reasoning":"Circuit breaker is appropriate and applied to the outage, but the state semantics are reversed: Closed is normal and Open fails fast. 'Opens again' should be 'closes again'. No clear drawback or tuning consideration is given beyond a threshold example.","evidence":[{"where":"Question 4","quote":"In the Open state calls pass through normally."},{"where":"Question 4","quote":"the breaker moves to Closed and calls fail immediately"}]},{"id":"C5","level":"Proficient","mark":3.0,"scale":6.0,"points":3.0,"max":6.0,"reasoning":"The menu choice and Redis cache technique are good. The payment choice is reasonable, but CAP is misused: partition tolerance is not optional; favouring consistency during a partition sacrifices availability. No concrete payment technique is named.","evidence":[{"where":"Question 5","quote":"The CAP theorem says a system can only provide two of consistency, availability and partition tolerance"},{"where":"Question 5","quote":"for payments we choose consistency and availability and give up partition tolerance."}]},{"id":"C6","level":"Proficient","mark":4.0,"scale":5.0,"points":4.0,"max":5.0,"reasoning":"Context, Decision and Consequences are specific and present. The consequences are all positive; no negative consequence is given, so it is Proficient rather than Excellent.","evidence":[{"where":"Question 6","quote":"Consequences: Placing an order no longer waits for the outlet, so the response time improves."}]},{"id":"C7","level":"Proficient","mark":3.0,"scale":4.0,"points":3.0,"max":4.0,"reasoning":"Headings and IEEE-style [1] are present, but Question 2 is about 181 words (over 150), [2] is cited without a reference entry, and no assumptions are stated. Writing is otherwise clear.","evidence":[{"where":"Question 4","quote":"The Circuit Breaker pattern [2]"},{"where":"References","quote":"[1] L. Bass, P. Clements, and R. Kazman"}]}]}
